using UnityEngine;

public static class Vector3Extensions
{
	public static bool CheckIfNotVisible(this Vector3 v, float xbounds, float ybounds, Camera camera)
	{
		Vector3 vector = camera.WorldToViewportPoint(v);
		if (!(vector.x < 0f - xbounds) && !(vector.x > 1f + xbounds) && !(vector.y < 0f - ybounds))
		{
			return vector.y > 1f + ybounds;
		}
		return true;
	}

	public static bool CheckIfNotVisible(this Vector3 v, float leftXBound, float rightXBound, float downYBound, float upYBound, Camera camera)
	{
		Vector3 vector = camera.WorldToViewportPoint(v);
		if (!(vector.x < 0f - leftXBound) && !(vector.x > 1f + rightXBound) && !(vector.y < 0f - downYBound))
		{
			return vector.y > 1f + upYBound;
		}
		return true;
	}

	public static Quaternion LookAtTarget(Vector3 targetDirection, int angleFactor)
	{
		float num = Mathf.Atan2(targetDirection.y, targetDirection.x) * 57.29578f;
		return Quaternion.Euler(0f, 0f, num + (float)angleFactor);
	}

	public static Vector3 Rotate90CW(this Vector3 dir)
	{
		return new Vector3(dir.y, 0f - dir.x, 0f);
	}

	public static Vector3 Rotate90CCW(this Vector3 dir)
	{
		return new Vector3(0f - dir.y, dir.x, 0f);
	}

	public static void Invert(this Vector3 vector)
	{
		vector.x = 0f - vector.x;
		vector.y = 0f - vector.y;
		vector.z = 0f - vector.z;
	}

	public static Vector2 ConvertToVector2(this Vector3 vector)
	{
		return new Vector2(vector.x, vector.y);
	}

	public static Vector3 ZeroZ(this Vector3 vector)
	{
		return new Vector3(vector.x, vector.y, 0f);
	}

	public static Vector3 SetZ(this Vector3 vector, float z)
	{
		return new Vector3(vector.x, vector.y, z);
	}
}
